typedef void (*virtual_fn)(void *, bool);
typedef void (*controller_fn)(void *);
#define assert(x) ((void) 0)

struct entity
{
  unsigned char pad[8];
  struct vtable_t
  {
    unsigned char pad[0x160];
    short delta;
    short unused;
    virtual_fn set_visible;
  } *vtable;

  void set_visible(bool value)
  {
    vtable->set_visible((char *) this + vtable->delta, value);
  }
};

struct kellyslater_controller
{
  int active;
  unsigned char pad0[4];
  struct vtable_t
  {
    unsigned char pad0[0x18];
    short kill_delta;
    short unused0;
    controller_fn kill;
    short resurrect_delta;
    short unused1;
    controller_fn resurrect;
  } *vtable;
  unsigned char pad1[0xe3c];
  entity *my_board;
  entity *my_board_model;
  entity *my_board_member;

  bool is_active() const { return active; }
  void set_active(bool yorn)
  {
    if (is_active())
    {
      if (!yorn)
        vtable->kill((char *) this + vtable->kill_delta);
    }
    else if (yorn)
      vtable->resurrect((char *) this + vtable->resurrect_delta);
  }
  entity *GetBoard(void) { return my_board; }
  entity *GetBoardModel(void) { return my_board_model; }
  entity *GetBoardMember(void) { return my_board_member; }
};

struct world_dynamics_system
{
  unsigned char pad[0xf0];
  kellyslater_controller *ks_controller[2];
  entity *hero_ptr[2];

  entity *get_hero_ptr(int n) { return hero_ptr[n]; }
  kellyslater_controller *get_ks_controller(int n) { return ks_controller[n]; }
};

class game
{
public:
  unsigned char pad0[0xc];
  world_dynamics_system *the_world;
  unsigned char pad1[0xa0];
  int num_players;
  unsigned char pad2[8];
  int active_player;

  void set_active_player(const int n);
};

void game::set_active_player(const int n)
{
	assert(n >= 0 && n < num_players);

	active_player = n;

	// Set this player to active, and all the rest to inactive.
	for (int i = 0; i < num_players; i++)
	{
		// Note: when changing these, change the code in retry_level too.
		the_world->get_ks_controller(i)->set_active(active_player == i);
		the_world->get_hero_ptr(i)->set_visible(active_player == i);
		the_world->get_ks_controller(i)->GetBoard()->set_visible(active_player == i);
		the_world->get_ks_controller(i)->GetBoardModel()->set_visible(active_player == i);
		the_world->get_ks_controller(i)->GetBoardMember()->set_visible(active_player == i);
	}
}
